def solve(D_sat_over_Dmax=0.5, eta_max=1.0):
    x_sat = D_sat_over_Dmax
    if x_sat >= 1.0:
        overall_fraction = eta_max / (3.0 * x_sat ** 2)
    else:
        below_sat = eta_max * x_sat / 3.0
        above_sat = eta_max * (1.0 - x_sat)
        overall_fraction = below_sat + above_sat
    overall_percent = overall_fraction * 100.0
    return {'1': {'value': overall_percent, 'unit': '%'}}

